use xiom.io;

type Person = {
  name: Str;
  age: Int;
}

fn main() -> Int {
  let me = Person{ name: "Alex", age: 15 };
  let friend = Person{ name: "Jordan", age: 16 };
  io.println(me.name.to_str());
  io.println(me.age.to_str());
  io.println(friend.name.to_str());
  io.println(friend.age.to_str());
  return 0;
}
